INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'choice', 3, '{"stem": "选择(3)：右图是由5个相同的小长方形拼成的，小长方形的长是6厘米，那么拼成的大长方形的周长是（  ）。A.16厘米  B.32厘米  C.40厘米"}', 'B', '小长方形宽=6÷3=2cm(3条宽=1条长); 大长方形长=6+2+2=10, 宽=6, 周长=(10+6)×2=32', 'jsj3_sx_v122', '["jsj3_sx","qimo2","p118","choice_03"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 2, '{"stem": "应用(1)：青少年活动中心里学习舞蹈的有68人，学习绘画的是学习舞蹈的3倍少15人，学习绘画的有多少人？"}', '189（人）', '68×3-15=204-15=189', 'jsj3_sx_v122', '["jsj3_sx","qimo2","p118","apply_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 3, '{"stem": "应用(2)：学校有篮球15个，足球12个，排球的个数是篮球的2倍多6个，排球有多少个？足球比排球少多少个？"}', '36个, 24个', '排球=15×2+6=36; 足球比排球少=36-12=24', 'jsj3_sx_v122', '["jsj3_sx","qimo2","p118","apply_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1026, '数学', '三年级', 'apply', 2, '{"stem": "应用(3)：36个学生和2个老师一起坐船游湖，每船限坐6人，至少要租几条船？"}', '7（条）', '36+2=38人, 38÷6=6...2, 6+1=7条', 'jsj3_sx_v122', '["jsj3_sx","qimo2","p119","apply_03"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1025, '数学', '三年级', 'apply', 3, '{"stem": "应用(4)：500毫米长的钢绳售价是3元，1米长的棉绳的售价是5元，哪种绳子更便宜？"}', '棉绳更便宜', '1米=1000毫米, 500×2=1000毫米→钢绳3×2=6元; 棉绳5元; 6>5→棉绳更便宜', 'jsj3_sx_v122', '["jsj3_sx","qimo2","p119","apply_04"]', 1, NULL);
