INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, '数学', '三年级', 'apply', 3, '{"stem": "应用(6)：沿公路一旁埋9根电线杆，每相邻两根之间的距离是50米，后来全部改装，只埋了6根。改装后，每相邻的两根电线杆之间的距离是多少米？"}', '80（米）', '原: (9-1)×50=400米; 新: 400÷(6-1)=80', 'jsj3_sx_v122', '["jsj3_sx","qimo2","p119","apply_06"]', 1, NULL);